package com.cpf.starter.tabular;import java.io.*;import java.nio.file.*;import java.util.*;import org.apache.poi.ss.usermodel.*;import org.apache.poi.xssf.usermodel.XSSFWorkbook;
public final class CpfXlsxService {private final int maxRows;private final int maxColumns;public CpfXlsxService(int r,int c){maxRows=r;maxColumns=c;}
 public List<List<String>> read(Path file)throws IOException{try(InputStream in=Files.newInputStream(file);Workbook wb=WorkbookFactory.create(in)){Sheet s=wb.getSheetAt(0);if(s.getLastRowNum()+1>maxRows)throw new IOException("XLSX row limit exceeded");DataFormatter f=new DataFormatter(Locale.ROOT);List<List<String>> rows=new ArrayList<>();for(Row row:s){if(row.getLastCellNum()>maxColumns)throw new IOException("XLSX column limit exceeded");List<String> values=new ArrayList<>();for(int i=0;i<Math.max(0,row.getLastCellNum());i++)values.add(f.formatCellValue(row.getCell(i,Row.MissingCellPolicy.CREATE_NULL_AS_BLANK)));rows.add(List.copyOf(values));}return List.copyOf(rows);}}
 public void write(Path file,List<List<String>> rows)throws IOException{if(rows.size()>maxRows)throw new IOException("XLSX row limit exceeded");Files.createDirectories(file.toAbsolutePath().getParent());try(Workbook wb=new XSSFWorkbook();OutputStream out=Files.newOutputStream(file)){Sheet s=wb.createSheet("data");for(int r=0;r<rows.size();r++){if(rows.get(r).size()>maxColumns)throw new IOException("XLSX column limit exceeded");Row row=s.createRow(r);for(int c=0;c<rows.get(r).size();c++)row.createCell(c,CellType.STRING).setCellValue(rows.get(r).get(c));}wb.write(out);}}}
